SELECT s.sid, s.serial#, s.username, s.osuser, s.machine, s.program, l.mode_held
FROM v$session s JOIN v$lock l ON s.sid = l.sid
WHERE l.block > 0;

SELECT a.object_name, b.oracle_username, b.os_user_name, c.sid, c.serial#
FROM all_objects a, v$locked_object b, v$session c
WHERE a.object_id = b.object_id AND b.session_id = c.sid;
